:root {
  color-scheme: dark;
  --et-black: #0a0f17;
  --et-black-rgb: 10 15 23;
  --et-deep-navy: #111627;
  --et-deep-navy-rgb: 17 22 39;
  --et-dark-blue: #1c2333;
  --et-dark-blue-rgb: 28 35 51;
  --et-muted-blue: #2f3c68;
  --et-muted-blue-rgb: 47 60 104;
  --et-dust-blue: #2f3c68;
  --et-dust-blue-rgb: 47 60 104;
  --et-cobalt: #486efe;
  --et-cobalt-rgb: 72 110 254;
  --et-sky-blue: #486efe;
  --et-sky-blue-rgb: 72 110 254;
  --et-lavender-blue: #d0ccf0;
  --et-lavender-blue-rgb: 208 204 240;
  --et-pastel: #d0ccf0;
  --et-pastel-rgb: 208 204 240;
  --et-mint: #01eab2;
  --et-mint-rgb: 1 234 178;
  --et-silver: #b0afb2;
  --et-silver-rgb: 176 175 178;
  --et-pale-silver: #ffffff;
  --et-pale-silver-rgb: 255 255 255;
  --et-surface: var(--et-deep-navy);
  --et-white-rgb: 255 255 255;
  --et-surface-muted: var(--et-black);
  --et-surface-depth: color-mix(in srgb, var(--et-black) 76%, var(--et-dust-blue) 24%);
  --et-brain-paper: var(--et-black);
  --et-brain-depth: color-mix(in srgb, var(--et-black) 72%, var(--et-dark-blue) 28%);
  --et-brain-edge: color-mix(in srgb, var(--et-dust-blue) 74%, var(--et-pastel) 26%);
  --et-panel: rgb(var(--et-deep-navy-rgb) / 0.72);
  --et-panel-solid: color-mix(in srgb, var(--et-deep-navy) 82%, var(--et-dust-blue) 18%);
  --et-panel-muted: color-mix(in srgb, var(--et-dark-blue) 82%, var(--et-muted-blue) 18%);
  --et-border: rgb(var(--et-pastel-rgb) / 0.12);
  --et-border-soft: rgb(var(--et-silver-rgb) / 0.18);
  --et-border-active: rgb(var(--et-cobalt-rgb) / 0.38);
  --et-shadow: 0 24px 70px rgb(0 0 0 / 0.34);
  --et-shadow-soft: 0 14px 36px rgb(0 0 0 / 0.28);
  --et-ink: var(--et-pale-silver);
  --et-navy: var(--et-dark-blue);
  --et-steel: var(--et-dark-blue);
  --et-indigo: var(--et-dust-blue);
  --et-dust: var(--et-dust-blue);
  --et-blue: var(--et-cobalt);
  --et-teal: var(--et-mint);
  --et-sky: var(--et-sky-blue);
  --et-lavender: var(--et-lavender-blue);
  --et-mist: var(--et-silver);
  --et-hot: var(--et-mint);
  --et-doc: var(--et-mint);
  --et-bad: var(--et-cobalt);
  font-family:
    Inter,
    "Space Grotesk",
    "Segoe UI",
    system-ui,
    sans-serif;
  background: var(--et-black);
  color: var(--et-ink);
}

/* BFO-8: Chat as a brain-first MCP client, not a detached transcript. */
.neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-operation-chat {
  grid-template-rows: minmax(430px, 52vh) auto !important;
}

.neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-primary {
  grid-template-columns: minmax(0, 1.72fr) minmax(330px, 0.76fr) !important;
}

.neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-brain-stage {
  min-height: min(560px, 52vh) !important;
}

.neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-command-surface {
  min-height: 0 !important;
  overflow: auto !important;
  border-color: rgb(var(--et-mint-rgb) / 0.18) !important;
  background:
    radial-gradient(ellipse at 16% 0%, rgb(var(--et-mint-rgb) / 0.12), transparent 46%),
    radial-gradient(ellipse at 100% 8%, rgb(var(--et-cobalt-rgb) / 0.12), transparent 42%),
    linear-gradient(145deg, rgb(var(--et-deep-navy-rgb) / 0.7), rgb(var(--et-black-rgb) / 0.34)) !important;
}

.agent-chat-brain-scene {
  position: absolute;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(ellipse at 48% 50%, rgb(var(--et-mint-rgb) / 0.075), transparent 42%),
    radial-gradient(ellipse at 22% 78%, rgb(var(--et-cobalt-rgb) / 0.11), transparent 38%);
}

.agent-chat-brain-scene::after {
  position: absolute;
  inset: 0;
  z-index: 3;
  content: "";
  pointer-events: none;
  background:
    linear-gradient(180deg, rgb(var(--et-black-rgb) / 0.26), transparent 20%, transparent 78%, rgb(var(--et-black-rgb) / 0.34)),
    repeating-linear-gradient(90deg, transparent 0 58px, rgb(var(--et-mint-rgb) / 0.025) 59px, transparent 60px);
  mix-blend-mode: screen;
  opacity: 0.72;
}

.agent-chat-truth-ribbon {
  position: absolute;
  top: 14px;
  left: 14px;
  right: 14px;
  z-index: 8;
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(160px, 0.56fr) minmax(0, 1fr) minmax(220px, 0.9fr);
  gap: 12px;
  align-items: center;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.1);
  border-radius: 9px;
  padding: 10px 12px;
  background:
    linear-gradient(135deg, rgb(var(--et-black-rgb) / 0.74), rgb(var(--et-deep-navy-rgb) / 0.62)),
    rgb(var(--et-black-rgb) / 0.36);
  box-shadow: 0 18px 44px rgb(0 0 0 / 0.22), inset 0 0 0 1px rgb(var(--et-white-rgb) / 0.025);
  backdrop-filter: blur(14px);
}

.agent-chat-truth-ribbon-ready {
  border-color: rgb(var(--et-mint-rgb) / 0.26);
  box-shadow: 0 18px 44px rgb(0 0 0 / 0.22), 0 0 32px rgb(var(--et-mint-rgb) / 0.08);
}

.agent-chat-truth-ribbon-running {
  border-color: rgb(var(--et-cobalt-rgb) / 0.34);
}

.agent-chat-truth-ribbon span,
.agent-chat-truth-ribbon em {
  overflow: hidden;
  color: rgb(var(--et-silver-rgb) / 0.68);
  font-size: 9.5px;
  font-style: normal;
  font-weight: 820;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.agent-chat-truth-ribbon strong {
  overflow: hidden;
  color: rgb(var(--et-pale-silver-rgb) / 0.94);
  font-size: 13px;
  font-weight: 860;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-chat-brain-canvas {
  position: absolute;
  inset: 0;
  z-index: 1;
}

.agent-chat-brain-canvas .brain-3d-inline {
  width: 100% !important;
  height: 100% !important;
  min-height: 100% !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
}

.agent-chat-brain-canvas .brain-3d-topbar,
.agent-chat-brain-canvas .brain-3d-footer {
  display: none !important;
}

.agent-chat-brain-overlays {
  position: absolute;
  left: 14px;
  right: 14px;
  bottom: 14px;
  z-index: 8;
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(150px, 0.48fr) minmax(180px, 0.58fr);
  gap: 10px;
}

.agent-chat-brain-overlays article {
  min-width: 0;
  display: grid;
  gap: 4px;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.1);
  border-radius: 8px;
  padding: 10px 11px;
  background:
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.68), rgb(var(--et-deep-navy-rgb) / 0.5)),
    rgb(var(--et-black-rgb) / 0.28);
  backdrop-filter: blur(12px);
}

.agent-chat-brain-overlays span,
.agent-chat-command-copy span,
.agent-selected-turn-card dt {
  color: rgb(var(--et-pastel-rgb) / 0.74);
  font-size: 9.5px;
  font-weight: 830;
  text-transform: uppercase;
}

.agent-chat-brain-overlays strong {
  overflow: hidden;
  color: rgb(var(--et-pale-silver-rgb) / 0.92);
  font-size: 12.5px;
  line-height: 1.28;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-chat-brain-overlays small {
  overflow: hidden;
  color: rgb(var(--et-silver-rgb) / 0.64);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-chat-command-panel,
.agent-selected-turn-card {
  min-width: 0;
  display: grid;
  gap: 10px;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.18);
  border-radius: 9px;
  padding: 10px;
  background:
    radial-gradient(ellipse at 20% 0%, rgb(var(--et-mint-rgb) / 0.1), transparent 46%),
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.44), rgb(var(--et-deep-navy-rgb) / 0.26));
}

.agent-chat-command-copy {
  display: grid;
  gap: 4px;
}

.agent-chat-command-copy strong {
  color: rgb(var(--et-pale-silver-rgb) / 0.94);
  font-size: 17px;
  line-height: 1.16;
}

.agent-chat-command-copy p,
.agent-selected-turn-card p {
  margin: 0;
  color: rgb(var(--et-silver-rgb) / 0.7);
  font-size: 11.5px;
  line-height: 1.42;
}

.neural-cockpit.shell-v2[class*="shell-option-"] .agent-chat-composer-command {
  grid-template-columns: 1fr !important;
  gap: 8px !important;
  border-color: rgb(var(--et-silver-rgb) / 0.1) !important;
  padding: 8px !important;
  background: rgb(var(--et-black-rgb) / 0.24) !important;
}

.agent-chat-composer-command textarea {
  min-height: 76px;
  max-height: 104px;
}

.agent-chat-composer-command .agent-run-turn {
  width: 100%;
  min-height: 42px;
}

.agent-chat-command-panel .agent-policy-strip-compact {
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  gap: 6px !important;
}

.agent-chat-command-panel .agent-policy-toggle {
  min-height: 31px;
  justify-content: center;
  padding: 6px 7px;
}

.agent-selected-turn-card dl {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 7px;
  margin: 0;
}

.agent-selected-turn-card dl > div {
  min-width: 0;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.09);
  border-radius: 7px;
  padding: 7px 8px;
  background: rgb(var(--et-black-rgb) / 0.22);
}

.agent-selected-turn-card dd {
  overflow: hidden;
  margin: 3px 0 0;
  color: rgb(var(--et-pale-silver-rgb) / 0.88);
  font-size: 11px;
  font-weight: 780;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-turn-list-command {
  max-height: 214px;
  border-color: rgb(var(--et-silver-rgb) / 0.1);
  background: rgb(var(--et-black-rgb) / 0.2);
  box-shadow: none;
}

.agent-brain-evidence .mode-panel {
  box-shadow: 0 18px 42px rgb(0 0 0 / 0.14) !important;
}

.agent-brain-evidence .mode-panel:first-child {
  grid-column: span 2;
  min-height: 330px !important;
}

.agent-brain-evidence .mode-panel:nth-child(3) {
  grid-column: span 2;
}

.agent-transcript-panel {
  min-height: 0;
  max-height: min(420px, 46vh);
  overflow: auto;
  display: grid;
  align-content: start;
  gap: 14px;
  padding: 4px 8px 4px 0;
  scrollbar-color: rgb(var(--et-mint-rgb) / 0.42) transparent;
  scrollbar-width: thin;
}

.agent-transcript-panel::-webkit-scrollbar,
.agent-turn-list-command::-webkit-scrollbar {
  width: 8px;
}

.agent-transcript-panel::-webkit-scrollbar-thumb,
.agent-turn-list-command::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgb(var(--et-mint-rgb) / 0.36);
  background-clip: padding-box;
}

.agent-transcript-panel .agent-chat-bubble {
  max-width: min(760px, 88%);
}

.agent-transcript-panel .agent-chat-bubble p {
  white-space: normal;
}

.agent-brain-evidence .agent-tool-card-stack,
.agent-brain-evidence .agent-state-panel,
.agent-brain-evidence .agent-tool-timeline,
.agent-brain-evidence .agent-context-digest,
.agent-brain-evidence .agent-answer-demo {
  border-color: rgb(var(--et-silver-rgb) / 0.1);
  background:
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.4), rgb(var(--et-deep-navy-rgb) / 0.14)),
    rgb(var(--et-white-rgb) / 0.02);
  box-shadow: none;
}

@media (max-width: 1180px) {
  .neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-primary,
  .neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-evidence.brain-first-contracts {
    grid-template-columns: 1fr !important;
  }

  .neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-command-surface {
    order: -1;
    overflow: visible !important;
  }

  .agent-brain-evidence .mode-panel:first-child,
  .agent-brain-evidence .mode-panel:nth-child(3) {
    grid-column: auto;
  }
}

@media (max-width: 760px) {
  .neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-operation-chat {
    grid-template-rows: auto auto !important;
  }

  .neural-cockpit.shell-v2[class*="shell-option-"] .mode-stage-chat .brain-first-brain-stage {
    min-height: min(420px, 55vh) !important;
  }

  .agent-chat-truth-ribbon,
  .agent-chat-brain-overlays {
    left: 10px;
    right: 10px;
    grid-template-columns: 1fr;
  }

  .agent-chat-truth-ribbon {
    gap: 4px;
    padding: 8px 9px;
  }

  .agent-chat-truth-ribbon em,
  .agent-chat-brain-overlays article:nth-child(n + 2) {
    display: none;
  }

  .agent-chat-command-panel .agent-policy-strip-compact,
  .agent-selected-turn-card dl {
    grid-template-columns: 1fr !important;
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  min-height: 100%;
  margin: 0;
}

body {
  overflow: hidden;
  background:
    radial-gradient(circle at 8% 18%, rgb(var(--et-mint-rgb) / 0.095), transparent 24%),
    radial-gradient(circle at 82% 8%, rgb(var(--et-cobalt-rgb) / 0.12), transparent 30%),
    radial-gradient(circle at 56% 78%, rgb(var(--et-lavender-blue-rgb) / 0.08), transparent 36%),
    linear-gradient(180deg, var(--et-black) 0%, color-mix(in srgb, var(--et-black) 78%, var(--et-dark-blue) 22%) 100%);
}

button {
  font: inherit;
}

.neural-cockpit {
  min-width: 1180px;
  height: 100vh;
  display: grid;
  grid-template-rows: 64px minmax(0, 1fr) 48px;
  gap: 9px;
  padding: 10px;
}

.et-timeline,
.mission-composer,
.brain-status-stack,
.brain-core-label,
.brain-view-tools {
  border: 1px solid var(--et-border);
  border-radius: 8px;
  background: var(--et-panel);
  box-shadow: var(--et-shadow);
  backdrop-filter: blur(20px);
}

.et-topbar {
  display: grid;
  grid-template-columns:
    minmax(196px, 0.88fr)
    minmax(176px, 0.78fr)
    minmax(220px, 1fr)
    repeat(5, minmax(94px, 0.48fr));
  gap: 8px;
  align-items: center;
  border-bottom: 1px solid rgb(var(--et-silver-rgb) / 0.22);
  padding: 0 2px 9px;
}

.et-brand,
.status-tile,
.brain-selector,
.et-command {
  min-width: 0;
  min-height: 46px;
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.16);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.72), rgb(var(--et-white-rgb) / 0.48));
  padding: 0 10px;
}

.et-brand {
  border-color: rgb(var(--et-dark-blue-rgb) / 0.08);
  background:
    linear-gradient(135deg, rgb(var(--et-white-rgb) / 0.92), color-mix(in srgb, var(--et-surface) 90%, var(--et-pastel) 10%));
}

.status-tile {
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.82), rgb(var(--et-white-rgb) / 0.56));
}

.brain-selector {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
  align-content: center;
}

.status-tile.ready {
  border-color: rgb(var(--et-mint-rgb) / 0.24);
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.86), rgb(var(--et-mint-rgb) / 0.055));
}

.status-tile.active {
  border-color: rgb(var(--et-cobalt-rgb) / 0.28);
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.86), rgb(var(--et-cobalt-rgb) / 0.06));
}

.status-tile.pending {
  border-color: rgb(var(--et-silver-rgb) / 0.22);
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.78), rgb(var(--et-pastel-rgb) / 0.08));
}

.status-tile.degraded {
  border-color: rgb(var(--et-dust-blue-rgb) / 0.26);
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.8), rgb(var(--et-dust-blue-rgb) / 0.07));
}

.et-mark {
  flex: 0 0 auto;
  width: 36px;
  height: 36px;
}

.et-brand strong,
.brain-selector strong,
.status-tile strong {
  display: block;
  overflow: hidden;
  color: var(--et-ink);
  font-size: 11px;
  letter-spacing: 0;
  line-height: 1.08;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.et-brand span,
.brain-selector span,
.status-tile span,
.et-command span,
.proof-title span,
.mission-composer span,
.brain-top-readout span,
.brain-core-label span {
  display: block;
  color: rgb(var(--et-dark-blue-rgb) / 0.6);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0;
  line-height: 1.12;
  text-transform: uppercase;
}

.status-tile div,
.et-brand div {
  min-width: 0;
}

.brain-selector-kicker {
  display: flex;
  align-items: center;
  gap: 5px;
}

.brain-selector-kicker svg {
  color: var(--et-mint);
}

.brain-selector-control {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 16px;
  gap: 6px;
  align-items: center;
}

.brain-selector-control svg {
  color: var(--et-mint);
  filter: drop-shadow(0 0 10px rgb(var(--et-mint-rgb) / 0.28));
  pointer-events: none;
}

.brain-selector select {
  appearance: none;
  width: 100%;
  min-width: 0;
  border: 0;
  outline: 0;
  color: var(--et-ink);
  background: transparent;
  font: inherit;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: uppercase;
  cursor: pointer;
}

.brain-selector select:disabled,
.brain-selector.error strong {
  color: rgb(var(--et-silver-rgb) / 0.72);
}

.status-tile i {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--et-pastel);
}

.status-tile i.ready {
  background: var(--et-mint);
  box-shadow: 0 0 12px rgb(var(--et-mint-rgb) / 0.38);
}

.status-tile i.active {
  background: var(--et-blue);
  box-shadow: 0 0 12px rgb(var(--et-cobalt-rgb) / 0.48);
}

.status-tile i.pending {
  background: var(--et-pastel);
  box-shadow: 0 0 10px rgb(var(--et-pastel-rgb) / 0.38);
}

.status-tile i.degraded {
  background: var(--et-dust-blue);
  box-shadow: 0 0 10px rgb(var(--et-dust-blue-rgb) / 0.28);
}

.et-command {
  color: rgb(var(--et-dust-blue-rgb) / 0.72);
  background:
    linear-gradient(135deg, rgb(var(--et-white-rgb) / 0.8), rgb(var(--et-pastel-rgb) / 0.14));
}

.et-command svg {
  flex: 0 0 auto;
  color: var(--et-blue);
}

.et-workspace {
  min-height: 0;
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr) 316px;
  gap: 10px;
}

.et-rail {
  min-height: 0;
  border: 1px solid rgb(var(--et-dark-blue-rgb) / 0.92);
  border-radius: 8px;
  padding: 8px 6px;
  background:
    linear-gradient(180deg, var(--et-dark-blue), color-mix(in srgb, var(--et-dark-blue) 74%, var(--et-dust-blue) 26%));
  box-shadow: 0 18px 46px rgb(var(--et-dark-blue-rgb) / 0.16);
}

.et-rail button {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr;
  gap: 4px;
  place-items: center;
  min-height: 46px;
  margin: 0 0 4px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: rgb(var(--et-white-rgb) / 0.55);
  cursor: pointer;
  font-size: 8.8px;
  font-weight: 720;
  letter-spacing: 0.02em;
  text-align: center;
}

.et-rail button svg {
  justify-self: center;
  color: rgb(var(--et-white-rgb) / 0.62);
}

.et-rail button.active {
  border-color: rgb(var(--et-mint-rgb) / 0.34);
  background:
    linear-gradient(180deg, rgb(var(--et-cobalt-rgb) / 0.36), rgb(var(--et-mint-rgb) / 0.13));
