    radial-gradient(ellipse at 100% 0%, rgb(var(--et-pastel-rgb) / 0.1), transparent 46%),
    linear-gradient(145deg, rgb(var(--et-deep-navy-rgb) / 0.42), rgb(var(--et-black-rgb) / 0.2));
}

.mutation-proof-head span {
  overflow: hidden;
  color: rgb(var(--et-dust-blue-rgb) / 0.7);
  font-size: 9.5px;
  font-weight: 840;
  letter-spacing: 0;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mutation-proof-head strong {
  color: rgb(var(--et-pale-silver-rgb) / 0.96);
  font-size: 14px;
  font-weight: 860;
}

.mutation-proof-head p {
  margin: 0;
  color: rgb(var(--et-silver-rgb) / 0.76);
  font-size: 11.5px;
  line-height: 1.42;
}

.mutation-proof-run {
  width: 100%;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.28);
  border-radius: 8px;
  color: rgb(var(--et-pale-silver-rgb) / 0.94);
  background:
    linear-gradient(145deg, rgb(var(--et-mint-rgb) / 0.14), rgb(var(--et-cobalt-rgb) / 0.12)),
    rgb(var(--et-black-rgb) / 0.22);
  font-size: 11px;
  font-weight: 860;
  cursor: pointer;
}

.mutation-proof-run:disabled {
  border-color: rgb(var(--et-pastel-rgb) / 0.16);
  color: rgb(var(--et-silver-rgb) / 0.62);
  background: rgb(var(--et-black-rgb) / 0.22);
  cursor: not-allowed;
}

.mutation-proof-run svg {
  flex: 0 0 auto;
}

.mutation-proof-panel .definition-rows {
  max-height: 260px;
  overflow: auto;
  padding-right: 2px;
  scrollbar-color: rgb(var(--et-mint-rgb) / 0.36) transparent;
  scrollbar-width: thin;
}

.mutation-proof-panel .definition-rows dd {
  overflow: visible;
  line-height: 1.32;
  text-overflow: clip;
  white-space: normal;
}

.mutation-apply-panel {
  display: grid;
  gap: 11px;
}

.mutation-apply-head {
  display: grid;
  gap: 5px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.18);
  border-radius: 8px;
  padding: 10px 11px;
  background:
    radial-gradient(ellipse at 0% 0%, rgb(var(--et-pastel-rgb) / 0.11), transparent 44%),
    linear-gradient(145deg, rgb(var(--et-deep-navy-rgb) / 0.45), rgb(var(--et-black-rgb) / 0.2));
}

.mutation-apply-panel-ready .mutation-apply-head {
  border-color: rgb(var(--et-mint-rgb) / 0.26);
  background:
    radial-gradient(ellipse at 0% 0%, rgb(var(--et-mint-rgb) / 0.12), transparent 44%),
    linear-gradient(145deg, rgb(var(--et-deep-navy-rgb) / 0.45), rgb(var(--et-black-rgb) / 0.2));
}

.mutation-apply-head span,
.mutation-apply-operator label > span {
  overflow: hidden;
  color: rgb(var(--et-dust-blue-rgb) / 0.72);
  font-size: 9.5px;
  font-weight: 840;
  letter-spacing: 0;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.mutation-apply-head strong {
  color: rgb(var(--et-pale-silver-rgb) / 0.96);
  font-size: 14px;
  font-weight: 860;
}

.mutation-apply-head p {
  margin: 0;
  color: rgb(var(--et-silver-rgb) / 0.76);
  font-size: 11.5px;
  line-height: 1.42;
}

.mutation-apply-operator {
  display: grid;
  gap: 8px;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.1);
  border-radius: 8px;
  padding: 9px;
  background:
    linear-gradient(135deg, rgb(var(--et-black-rgb) / 0.28), rgb(var(--et-deep-navy-rgb) / 0.16)),
    rgb(var(--et-white-rgb) / 0.025);
}

.mutation-apply-operator label {
  min-width: 0;
  display: grid;
  gap: 6px;
}

.mutation-apply-operator input[type="text"] {
  min-width: 0;
  height: 34px;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.26);
  border-radius: 8px;
  padding: 0 10px;
  color: rgb(var(--et-pale-silver-rgb) / 0.92);
  background: rgb(var(--et-black-rgb) / 0.34);
  font-size: 11.5px;
  font-weight: 760;
  outline: none;
}

.mutation-apply-operator input[type="text"]:focus {
  border-color: rgb(var(--et-mint-rgb) / 0.42);
  box-shadow: 0 0 0 1px rgb(var(--et-mint-rgb) / 0.14);
}

.mutation-apply-consent {
  grid-template-columns: 16px minmax(0, 1fr);
  align-items: center;
  gap: 8px !important;
  color: rgb(var(--et-silver-rgb) / 0.78);
  font-size: 11px;
  font-weight: 780;
}

.mutation-apply-consent input {
  width: 14px;
  height: 14px;
  accent-color: rgb(var(--et-mint-rgb));
}

.mutation-apply-panel .definition-rows {
  max-height: 280px;
  overflow: auto;
  padding-right: 2px;
  scrollbar-color: rgb(var(--et-mint-rgb) / 0.34) transparent;
  scrollbar-width: thin;
}

.mutation-apply-panel .definition-rows dd {
  overflow: visible;
  line-height: 1.32;
  text-overflow: clip;
  white-space: normal;
}

.mutation-apply-execute {
  width: 100%;
  min-height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.18);
  border-radius: 8px;
  color: rgb(var(--et-silver-rgb) / 0.68);
  background: rgb(var(--et-black-rgb) / 0.27);
  font-size: 11px;
  font-weight: 860;
  cursor: not-allowed;
}

.mutation-apply-execute:not(:disabled) {
  border-color: rgb(var(--et-mint-rgb) / 0.44);
  color: rgb(var(--et-pale-silver-rgb) / 0.98);
  background:
    linear-gradient(145deg, rgb(var(--et-mint-rgb) / 0.22), rgb(var(--et-cobalt-rgb) / 0.16)),
    rgb(var(--et-black-rgb) / 0.18);
  cursor: pointer;
}

.evidence-list {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.evidence-list li {
  display: grid;
  gap: 3px;
  border-bottom: 1px solid rgb(var(--et-silver-rgb) / 0.14);
  padding-bottom: 7px;
}

.evidence-list li:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.evidence-list span,
.mode-empty-copy,
.mode-contract-copy,
.mode-empty-block p,
.flow-panel p,
.gate-row strong {
  margin: 0;
  color: rgb(var(--et-dust-blue-rgb) / 0.72);
  font-size: 12px;
  line-height: 1.45;
}

.mode-empty-block {
  display: grid;
  place-items: center;
  min-height: 212px;
  border: 1px dashed rgb(var(--et-cobalt-rgb) / 0.22);
  border-radius: 8px;
  padding: 18px;
  text-align: center;
  background: rgb(var(--et-white-rgb) / 0.5);
}

.mode-empty-block svg {
  color: var(--et-blue);
}

.mode-empty-block strong {
  color: var(--et-ink);
  font-size: 13px;
}

.mini-brain-context {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.mini-brain-context div,
.readiness-tile {
  min-width: 0;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.16);
  border-radius: 7px;
  padding: 10px;
  background:
    linear-gradient(145deg, rgb(var(--et-dark-blue-rgb) / 0.58), rgb(var(--et-black-rgb) / 0.38));
}

.mini-brain-context strong,
.readiness-tile strong {
  display: block;
  overflow: hidden;
  color: var(--et-pale-silver);
  font-size: 15px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mini-brain-context span,
.readiness-tile span {
  display: block;
  margin-top: 3px;
  color: rgb(var(--et-silver-rgb) / 0.66);
  font-size: 10px;
  font-weight: 740;
}

.route-ledger {
  display: grid;
  gap: 7px;
  max-height: 348px;
  overflow: auto;
}

.route-row {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 18px minmax(0, 1fr) minmax(78px, auto);
  gap: 8px;
  align-items: center;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.12);
  border-radius: 7px;
  padding: 8px 9px;
  background:
    radial-gradient(circle at 0% 50%, rgb(var(--et-cobalt-rgb) / 0.08), transparent 42%),
    rgb(var(--et-black-rgb) / 0.24);
}

.route-row strong {
  overflow: hidden;
  color: rgb(var(--et-pale-silver-rgb) / 0.92);
  font-size: 11.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.route-row svg {
  color: rgb(var(--et-clear-indigo-rgb) / 0.88);
}

.route-row em {
  justify-self: end;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.24);
  border-radius: 999px;
  padding: 3px 7px;
  color: rgb(var(--et-clear-indigo-rgb) / 0.94);
  background: rgb(var(--et-cobalt-rgb) / 0.09);
  font-size: 10px;
  font-style: normal;
  font-weight: 820;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.route-row-highway em {
  border-color: rgb(var(--et-mint-rgb) / 0.28);
  color: rgb(var(--et-bright-mint-rgb) / 0.92);
  background: rgb(var(--et-mint-rgb) / 0.1);
}

.route-row-spatial em {
  border-color: rgb(var(--et-pastel-rgb) / 0.8);
  color: rgb(var(--et-pastel-rgb) / 0.9);
  background: rgb(var(--et-pastel-rgb) / 0.22);
}

.route-row-run_projection em {
  border-color: rgb(var(--et-cobalt-rgb) / 0.22);
  color: var(--et-cobalt);
  background: rgb(var(--et-cobalt-rgb) / 0.08);
}

.growth-flow {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 24px minmax(0, 1fr) 24px minmax(0, 1fr);
  gap: 9px;
  align-items: stretch;
  margin-bottom: 12px;
}

.flow-panel {
  border: 1px solid var(--et-border);
  border-radius: 8px;
  padding: 15px;
  background: rgb(var(--et-white-rgb) / 0.68);
  box-shadow: 0 12px 32px rgb(var(--et-dark-blue-rgb) / 0.045);
}

.flow-panel-mock {
  border-color: rgb(var(--et-cobalt-rgb) / 0.18);
}

.flow-panel-blocked {
  border-color: rgb(var(--et-dust-blue-rgb) / 0.2);
  background:
    linear-gradient(145deg, rgb(var(--et-white-rgb) / 0.62), rgb(var(--et-pastel-rgb) / 0.13));
}

.flow-arrow {
  align-self: center;
  color: var(--et-blue);
}

.readiness-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 12px;
}

.readiness-tile-ready {
  border-color: rgb(var(--et-mint-rgb) / 0.24);
  background: rgb(var(--et-mint-rgb) / 0.08);
}

.readiness-tile-blocked {
  border-color: rgb(var(--et-dust-blue-rgb) / 0.22);
  background: rgb(var(--et-pastel-rgb) / 0.12);
}

.benchmark-board {
  display: grid;
  gap: 8px;
  margin-bottom: 12px;
}

.gate-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.18);
  border-radius: 8px;
  padding: 10px 12px;
  background: rgb(var(--et-white-rgb) / 0.66);
}

.gate-row strong {
  display: block;
  color: var(--et-ink);
  font-weight: 820;
}

.gate-row em {
  flex: 0 0 auto;
  border: 1px solid rgb(var(--et-dust-blue-rgb) / 0.18);
  border-radius: 999px;
  padding: 4px 8px;
  color: var(--et-dust-blue);
  background: rgb(var(--et-pastel-rgb) / 0.16);
  font-size: 10px;
  font-style: normal;
  font-weight: 820;
  text-transform: uppercase;
}

.mode-actions {
  min-height: 50px;
}

.mode-actions button {
  position: relative;
  max-width: 260px;
  min-height: 48px;
  align-items: start;
  justify-content: center;
  flex-direction: column;
  padding: 7px 10px 7px 32px;
  text-align: left;
}

.mode-actions button svg {
  position: absolute;
  left: 10px;
  top: 11px;
}

.mode-actions button span {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mode-actions button small {
  display: block;
  max-width: 100%;
  overflow: hidden;
  color: rgb(var(--et-dust-blue-rgb) / 0.58);
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.brain-stage-with-composer {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 10px;
  padding: 12px;
}

.brain-canvas-zone {
  position: relative;
  min-height: 0;
  overflow: hidden;
  border-radius: 6px;
}

.master-brain-projection,
.brain-pixi-host {
  position: absolute;
  inset: 0;
}

.master-brain-projection {
  z-index: 1;
}

.brain-pixi-host canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  cursor: crosshair;
}

.brain-pixi-host[data-ready="true"] {
  opacity: 1;
}

.brain-top-readout {
  position: absolute;
  top: 20px;
  left: 24px;
  pointer-events: none;
}

.brain-top-readout strong {
  display: block;
  margin-top: 7px;
  color: var(--et-ink);
  font-size: 22px;
  letter-spacing: 0.01em;
}

.brain-top-readout em {
  display: block;
  margin-top: 4px;
  color: rgb(var(--et-dust-blue-rgb) / 0.7);
  font-size: 11px;
  font-style: normal;
  font-weight: 760;
}

.brain-view-tools {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 178px;
  max-width: calc(100% - 28px);
  display: flex;
  align-items: stretch;
  justify-content: flex-start;
  flex-direction: column;
  flex-wrap: nowrap;
  gap: 6px;
  padding: 6px;
  background: rgb(var(--et-white-rgb) / 0.58);
  box-shadow: 0 10px 26px rgb(var(--et-dark-blue-rgb) / 0.045);
}

.brain-detail-select {
  display: grid;
  grid-template-columns: 1fr;
  gap: 4px;
  min-height: 28px;
  padding: 0;
}

.brain-detail-select span {
  color: rgb(var(--et-dark-blue-rgb) / 0.58);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.brain-detail-select select {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--et-border-active);
  border-radius: 6px;
  padding: 5px 7px;
  color: var(--et-blue);
  background: var(--et-surface);
  font: inherit;
  font-size: 11px;
  font-weight: 760;
}

.brain-view-tools button,
.mission-controls button,
.proof-tabs button,
.client-view {
  border: 1px solid var(--et-border-active);
  border-radius: 7px;
  background: rgb(var(--et-cobalt-rgb) / 0.055);
  color: var(--et-blue);
  cursor: pointer;
  font-size: 11px;
  font-weight: 760;
}

.brain-view-tools button:disabled,
.mission-controls button:disabled,
.client-view:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.brain-view-tools button {
  min-height: 28px;
  padding: 5px 8px;
}

.brain-view-tools button.active {
  border-color: rgb(var(--et-mint-rgb) / 0.44);
  color: var(--et-ink);
  background:
    linear-gradient(135deg, rgb(var(--et-mint-rgb) / 0.14), rgb(var(--et-pastel-rgb) / 0.2));
}

.brain-layer-controls {
  display: flex;
  align-items: stretch;
  flex-direction: column;
  flex-wrap: nowrap;
  gap: 5px;
  border-left: 0;
  border-top: 1px solid rgb(var(--et-silver-rgb) / 0.26);
  padding-top: 6px;
  padding-left: 0;
}

.brain-layer-controls label {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  align-items: center;
  gap: 5px;
  min-height: 28px;
}

.brain-layer-controls span {
  color: rgb(var(--et-dark-blue-rgb) / 0.58);
  font-size: 9.5px;
  font-weight: 780;
  letter-spacing: 0;
  text-transform: uppercase;
}

.brain-layer-controls select {
  width: 100%;
  min-width: 0;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.24);
  border-radius: 6px;
  padding: 4px 5px;
  color: var(--et-blue);
  background: var(--et-surface);
  font: inherit;
  font-size: 10.5px;
  font-weight: 760;
}

.brain-layer-controls button {
  padding-inline: 7px;
}

.brain-client-banner {
  position: absolute;
  top: 62px;
  right: 18px;
  z-index: 2;
  display: grid;
  gap: 3px;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.3);
  border-radius: 8px;
  padding: 9px 11px;
  background:
    linear-gradient(135deg, rgb(var(--et-white-rgb) / 0.78), rgb(var(--et-mint-rgb) / 0.1));
  box-shadow: 0 12px 30px rgb(var(--et-dark-blue-rgb) / 0.05);
  backdrop-filter: blur(18px);
}

.brain-client-banner span {
  color: rgb(var(--et-dust-blue-rgb) / 0.66);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brain-client-banner strong {
  color: var(--et-ink);
  font-size: 12px;
}

.brain-status-stack {
  position: absolute;
  left: 24px;
  right: auto;
  bottom: 18px;
  width: 168px;
  padding: 10px;
  background: rgb(var(--et-white-rgb) / 0.72);
  box-shadow: 0 10px 28px rgb(var(--et-dark-blue-rgb) / 0.055);
}

.brain-status-stack div {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  color: rgb(var(--et-dust-blue-rgb) / 0.78);
  font-size: 10.5px;
}

.brain-status-stack i {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.brain-error {
  position: absolute;
  top: 72px;
  left: 22px;
  z-index: 8;
  max-width: 520px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.18);
  border-radius: 8px;
  padding: 10px 12px;
  color: var(--et-text-muted);
  background:
    linear-gradient(145deg, rgb(var(--et-dark-blue-rgb) / 0.86), rgb(var(--et-black-rgb) / 0.58));
  box-shadow: 0 16px 42px rgb(0 0 0 / 0.28);
  font-size: 11px;
  font-weight: 760;
}

.brain-loader,
.brain-3d-loader {
  position: absolute;
  inset: 0;
  z-index: 8;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 10px;
  background:
    radial-gradient(circle at 46% 42%, rgb(var(--et-pastel-rgb) / 0.55), transparent 24%),
    linear-gradient(180deg, color-mix(in srgb, var(--et-surface) 84%, var(--et-silver) 16%), color-mix(in srgb, var(--et-surface) 70%, var(--et-silver) 30%));
  color: var(--et-ink);
  text-align: center;
  pointer-events: all;
}

.brain-loader strong,
.brain-3d-loader strong {
  font-size: 13px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.brain-loader span,
.brain-3d-loader span {
  color: rgb(var(--et-dark-blue-rgb) / 0.62);
  font-size: 11px;
  font-weight: 700;
}

.brain-loader-mark {
  position: relative;
  width: 58px;
  height: 34px;
}

.brain-loader-mark i {
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--et-blue);
  box-shadow: 0 0 18px rgb(var(--et-cobalt-rgb) / 0.5);
}

.brain-loader-mark i:nth-child(1) {
  left: 6px;
  top: 17px;
}

.brain-loader-mark i:nth-child(2) {
  left: 25px;
  top: 7px;
  background: var(--et-lavender);
}

.brain-loader-mark i:nth-child(3) {
  right: 6px;
  top: 18px;
  background: var(--et-sky);
}

.brain-loader-mark::before,
.brain-loader-mark::after {
  position: absolute;
  content: "";
  height: 1px;
  background: rgb(var(--et-cobalt-rgb) / 0.34);
  transform-origin: left center;
}

.brain-loader-mark::before {
  left: 13px;
  top: 19px;
  width: 22px;
  transform: rotate(-28deg);
}

.brain-loader-mark::after {
  left: 32px;
  top: 13px;
  width: 22px;
  transform: rotate(25deg);
}

.mission-composer {
  position: relative;
  left: auto;
  right: auto;
  bottom: auto;
  z-index: 4;
  width: auto;
  min-width: 0;
  padding: 9px;
  border-color: rgb(var(--et-silver-rgb) / 0.18);
  background:
    linear-gradient(180deg, rgb(var(--et-white-rgb) / 0.46), rgb(var(--et-white-rgb) / 0.28));
  box-shadow: 0 10px 28px rgb(var(--et-dark-blue-rgb) / 0.028);
  backdrop-filter: blur(10px);
}

.mission-composer-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 10px;
}

.mission-composer-head strong {
  color: var(--et-ink);
  font-size: 11px;
  font-weight: 820;
  letter-spacing: 0;
  text-transform: uppercase;
}

.mission-input {
  display: block;
  margin-top: 6px;
}

.mission-input input {
  width: 100%;
  min-height: 30px;
  border: 1px solid var(--et-border-soft);
  border-radius: 7px;
  padding: 0 11px;
  color: var(--et-ink);
  background: var(--et-surface);
  font: inherit;
  font-size: 13px;
}

.mission-input input::placeholder {
  color: rgb(var(--et-dark-blue-rgb) / 0.42);
}

.mission-controls {
  display: grid;
  grid-template-columns: minmax(260px, 1.12fr) minmax(220px, 0.9fr) minmax(150px, 0.58fr) minmax(116px, 0.42fr);
  gap: 6px;
  margin-top: 7px;
  align-items: end;
}

.mission-control-group {
  min-width: 0;
  margin: 0;
  border: 0;
  padding: 0;
}

.mission-control-group legend,
.mission-select-group span {
  margin-bottom: 5px;
  color: rgb(var(--et-dark-blue-rgb) / 0.58);
  font-size: 9.5px;
  font-weight: 820;
  letter-spacing: 0;
  text-transform: uppercase;
}

.segmented-control {
  display: grid;
  grid-auto-columns: minmax(0, 1fr);
  grid-auto-flow: column;
  min-height: 28px;
  overflow: hidden;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.22);
  border-radius: 7px;
  background: rgb(var(--et-white-rgb) / 0.68);
}

.mission-controls button,
.mission-select-group select,
.mission-toggle {
  min-height: 28px;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.24);
  background: rgb(var(--et-cobalt-rgb) / 0.045);
  color: var(--et-blue);
  font-size: 10px;
  font-weight: 780;
}

.segmented-control button {
  min-width: 0;
  border: 0;
  border-right: 1px solid rgb(var(--et-cobalt-rgb) / 0.16);
  border-radius: 0;
  padding: 0 7px;
  background: transparent;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}

.segmented-control button:last-child {
  border-right: 0;
}

.segmented-control button.active,
.mission-toggle.active {
  color: var(--et-ink);
  background:
    linear-gradient(135deg, rgb(var(--et-mint-rgb) / 0.14), rgb(var(--et-pastel-rgb) / 0.2));
}

.mission-select-group {
  min-width: 0;
  display: grid;
}

.mission-select-group select {
  width: 100%;
  border-radius: 7px;
  padding: 0 8px;
  font: inherit;
  font-size: 10.5px;
  cursor: pointer;
}

.mission-toggle {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border-radius: 7px;
  padding: 0 10px;
  cursor: pointer;
  white-space: nowrap;
}

.mission-toggle input {
  width: 12px;
  height: 12px;
  margin: 0;
  accent-color: var(--et-mint);
}

.mission-controls .run {
  border-color: rgb(var(--et-cobalt-rgb) / 0.36);
  border-radius: 7px;
  background:
    linear-gradient(135deg, var(--et-cobalt), color-mix(in srgb, var(--et-cobalt) 74%, var(--et-pastel) 26%));
  color: var(--et-surface);
  cursor: pointer;
}

.mission-strategy-group {
  grid-column: 1;
}

.mission-select-group {
  grid-column: 2;
}

.mission-toggle {
  grid-column: 1 / 3;
}

.proof-dock {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgb(var(--et-dark-blue-rgb) / 0.9);
  border-radius: 8px;
  padding: 16px;
  background:
    radial-gradient(circle at 14% 0%, rgb(var(--et-mint-rgb) / 0.13), transparent 34%),
    linear-gradient(180deg, var(--et-dark-blue), color-mix(in srgb, var(--et-dark-blue) 78%, var(--et-dust-blue) 22%));
  box-shadow: 0 24px 70px rgb(var(--et-dark-blue-rgb) / 0.2);
  scrollbar-color: rgb(var(--et-pastel-rgb) / 0.55) transparent;
  scrollbar-width: thin;
}

.proof-dock::-webkit-scrollbar {
  width: 8px;
}

.proof-dock::-webkit-scrollbar-track {
  background: transparent;
}

.proof-dock::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgb(var(--et-pastel-rgb) / 0.55);
  background-clip: padding-box;
}

.proof-title h2 {
  margin: 5px 0 15px;
  color: var(--et-surface);
  font-size: 19px;
}

.proof-title span {
  color: rgb(var(--et-pastel-rgb) / 0.72);
}

.proof-run-banner,
.selected-node-card {
  display: grid;
  gap: 3px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.13);
  border-radius: 8px;
  padding: 8px 10px;
  background:
    linear-gradient(145deg, rgb(var(--et-white-rgb) / 0.075), rgb(var(--et-pastel-rgb) / 0.04));
}

.proof-run-banner {
  margin-bottom: 10px;
}

.proof-run-banner span,
.selected-node-card span {
  color: rgb(var(--et-pastel-rgb) / 0.72);
  font-size: 9.5px;
  font-weight: 820;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.proof-run-banner strong,
.selected-node-card strong {
  overflow: hidden;
  color: var(--et-surface);
  font-size: 12px;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selected-node-card {
  flex: 0 0 auto;
  margin-top: 8px;
  border-color: rgb(var(--et-mint-rgb) / 0.24);
  background:
    radial-gradient(circle at 8% 0%, rgb(var(--et-mint-rgb) / 0.12), transparent 42%),
    linear-gradient(145deg, rgb(var(--et-white-rgb) / 0.08), rgb(var(--et-cobalt-rgb) / 0.06));
}

.selected-node-card p {
  margin: 0;
  color: color-mix(in srgb, var(--et-surface) 68%, var(--et-pastel) 32%);
  font-size: 10.5px;
  line-height: 1.35;
}

.proof-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.proof-tabs button {
  min-height: 32px;
  border-color: rgb(var(--et-pastel-rgb) / 0.18);
  color: rgb(var(--et-pastel-rgb) / 0.72);
  background: rgb(var(--et-white-rgb) / 0.045);
}

.proof-tabs button.active {
  border-color: rgb(var(--et-mint-rgb) / 0.46);
  color: var(--et-surface);
  background:
    linear-gradient(135deg, rgb(var(--et-cobalt-rgb) / 0.38), rgb(var(--et-mint-rgb) / 0.16));
}

.truth-ledger {
  flex: 0 0 auto;
  display: grid;
  gap: 0;
  margin-top: 12px;
}

.truth-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 7px 0;
  border-bottom: 1px solid rgb(var(--et-pastel-rgb) / 0.14);
  font-size: 11.5px;
}

.truth-row span {
  color: rgb(var(--et-pastel-rgb) / 0.68);
}

.truth-row strong {
  color: color-mix(in srgb, var(--et-surface) 74%, var(--et-mint) 26%);
  text-align: right;
}

.payload-preview {
  flex: 1 1 auto;
  display: grid;
  gap: 5px;
  margin-top: 10px;
  min-height: 82px;
  max-height: 208px;
  overflow: auto;
  border-radius: 8px;
  padding: 13px;
  color: color-mix(in srgb, var(--et-surface) 72%, var(--et-pastel) 28%);
  background:
    linear-gradient(145deg, rgb(var(--et-white-rgb) / 0.075), rgb(var(--et-pastel-rgb) / 0.05));
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.09);
  font: 11px/1.45 "IBM Plex Mono", Consolas, monospace;
  white-space: pre-wrap;
  scrollbar-color: rgb(var(--et-pastel-rgb) / 0.42) transparent;
  scrollbar-width: thin;
}

.payload-preview::-webkit-scrollbar {
  width: 8px;
}

.payload-preview::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgb(var(--et-pastel-rgb) / 0.42);
  background-clip: padding-box;
}

.document-proof-panel {
  gap: 10px;
  max-height: 356px;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  white-space: normal;
}

.document-panel-header,
.document-selected-header,
.document-raw-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.document-panel-header span,
.document-selected-header span {
  display: block;
  color: rgb(var(--et-pastel-rgb) / 0.62);
  font-size: 10px;
  font-weight: 820;
  text-transform: uppercase;
}

.document-panel-header strong,
.document-selected-header strong {
  display: block;
  margin-top: 3px;
  overflow: hidden;
  color: var(--et-surface);
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.document-panel-header small,
.document-selected-header small {
  color: rgb(var(--et-pastel-rgb) / 0.58);
  font-size: 10.5px;
  font-weight: 720;
}

.document-ref-list {
  display: grid;
  gap: 7px;
}

.document-ref-card {
  min-width: 0;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 3px 8px;
  align-items: start;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.12);
  border-radius: 8px;
  padding: 9px;
  color: color-mix(in srgb, var(--et-surface) 76%, var(--et-pastel) 24%);
  background:
    linear-gradient(135deg, rgb(var(--et-white-rgb) / 0.055), rgb(var(--et-dust-blue-rgb) / 0.1));
  text-align: left;
}

.document-ref-card.active {
  border-color: rgb(var(--et-mint-rgb) / 0.42);
  background:
    radial-gradient(circle at 0% 0%, rgb(var(--et-mint-rgb) / 0.14), transparent 42%),
    linear-gradient(135deg, rgb(var(--et-cobalt-rgb) / 0.18), rgb(var(--et-white-rgb) / 0.06));
}

.document-ref-card strong,
.document-ref-card small,
.document-ref-status {
  grid-column: 2;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.document-ref-card strong {
  color: var(--et-surface);
  font-size: 11.5px;
}

.document-ref-card small,
.document-ref-status {
  color: rgb(var(--et-pastel-rgb) / 0.62);
  font-size: 10px;
  font-weight: 720;
}

.document-ref-rank {
  grid-row: 1 / span 3;
  display: inline-flex;
  min-height: 24px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.26);
  border-radius: 999px;
  color: rgb(var(--et-mint-rgb) / 0.9);
  background: rgb(var(--et-mint-rgb) / 0.08);
  font-size: 10px;
  font-weight: 850;
}

.document-selected-panel {
  display: grid;
  gap: 9px;
  border-top: 1px solid rgb(var(--et-pastel-rgb) / 0.12);
  padding-top: 10px;
}

.document-hydrate-action {
  width: auto;
  min-height: 32px;
  padding: 0 12px;
  font-size: 11px;
  white-space: nowrap;
}

.document-ref-details {
  display: grid;
  gap: 5px;
}

.document-detail-row {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 8px;
  border-bottom: 1px solid rgb(var(--et-pastel-rgb) / 0.08);
  padding-bottom: 5px;
}

.document-detail-row span {
  color: rgb(var(--et-pastel-rgb) / 0.55);
  font-size: 10px;
  font-weight: 830;
  text-transform: uppercase;
}

.document-detail-row strong {
  min-width: 0;
  overflow: hidden;
  color: color-mix(in srgb, var(--et-surface) 78%, var(--et-pastel) 22%);
  font-size: 10.5px;
  font-weight: 720;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.document-raw-placeholder,
.document-hydration-error,
.document-panel-empty {
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.12);
  border-radius: 8px;
  padding: 10px;
  color: rgb(var(--et-pastel-rgb) / 0.68);
  background: rgb(var(--et-black-rgb) / 0.18);
  font-size: 11px;
  line-height: 1.4;
}

.document-hydration-error {
  border-color: rgb(255 110 110 / 0.34);
  color: rgb(255 178 178 / 0.92);
}

.document-panel-empty {
  display: grid;
  gap: 6px;
  justify-items: start;
}

.document-raw-viewer {
  display: grid;
  gap: 7px;
  min-height: 0;
}

.document-raw-meta {
  color: rgb(var(--et-pastel-rgb) / 0.58);
  font-size: 10px;
  font-weight: 780;
  text-transform: uppercase;
}

.document-raw-viewer pre {
  max-height: 170px;
  overflow: auto;
  margin: 0;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.14);
  border-radius: 8px;
  padding: 10px;
  color: color-mix(in srgb, var(--et-surface) 82%, var(--et-pastel) 18%);
  background: rgb(var(--et-black-rgb) / 0.34);
  font: 10.5px/1.42 "IBM Plex Mono", Consolas, monospace;
  white-space: pre-wrap;
}

.client-view {
  width: 100%;
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 12px;
  border-color: rgb(var(--et-mint-rgb) / 0.32);
  color: color-mix(in srgb, var(--et-surface) 78%, var(--et-mint) 22%);
  background: linear-gradient(135deg, rgb(var(--et-cobalt-rgb) / 0.24), rgb(var(--et-mint-rgb) / 0.1));
}

.client-view:not(:disabled) {
  opacity: 1;
  box-shadow: inset 0 0 0 1px rgb(var(--et-mint-rgb) / 0.18);
}

.client-view.active {
  border-color: rgb(var(--et-mint-rgb) / 0.52);
  color: var(--et-surface);
  background:
    linear-gradient(135deg, var(--et-cobalt), color-mix(in srgb, var(--et-mint) 38%, var(--et-cobalt) 62%));
}

.proof-action-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 8px;
  margin-top: 12px;
}

.proof-action-row .client-view {
  margin-top: 0;
}

.proof-action {
  min-height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.28);
  border-radius: 8px;
  color: rgb(var(--et-pale-silver-rgb) / 0.9);
  background:
    linear-gradient(135deg, rgb(var(--et-dust-blue-rgb) / 0.32), rgb(var(--et-black-rgb) / 0.42));
  cursor: pointer;
}

.proof-action:not(:disabled) {
  box-shadow: inset 0 0 0 1px rgb(var(--et-mint-rgb) / 0.08);
}

.proof-action:not(:disabled):hover {
  border-color: rgb(var(--et-mint-rgb) / 0.42);
  color: rgb(var(--et-bright-mint-rgb) / 0.92);
}

.proof-action:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.et-timeline {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  gap: 5px;
  align-items: center;
  padding: 7px 9px;
  background: rgb(var(--et-white-rgb) / 0.66);
}

.time-step {
  min-width: 0;
  display: grid;
  grid-template-columns: 8px minmax(0, 1fr);
  gap: 5px;
  align-items: start;
}

.time-step i {
  width: 6px;
  height: 6px;
  margin-top: 5px;
  border-radius: 50%;
  background: var(--et-lavender);
}

.time-step.done i {
  background: var(--et-blue);
  box-shadow: 0 0 12px rgb(var(--et-cobalt-rgb) / 0.58);
}

.time-step strong,
.time-step span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.time-step strong {
  color: var(--et-ink);
  font-size: 9.5px;
}

.time-step span {
  margin-top: 2px;
  color: rgb(var(--et-dark-blue-rgb) / 0.56);
  font-size: 9px;
}

.brain-3d-modal {
  position: fixed;
  inset: 14px;
  z-index: 30;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid var(--et-border-active);
  border-radius: 10px;
  background-color: var(--et-surface);
  background:
    linear-gradient(135deg, var(--et-surface), color-mix(in srgb, var(--et-surface) 82%, var(--et-silver) 12%, var(--et-pastel) 6%));
  box-shadow: 0 30px 80px rgb(var(--et-dark-blue-rgb) / 0.22);
}

.brain-3d-modal::before {
  position: absolute;
  inset: 0;
  z-index: 0;
  content: "";
  background:
    radial-gradient(ellipse at 20% 20%, rgb(var(--et-mint-rgb) / 0.095), transparent 28%),
    radial-gradient(ellipse at 74% 18%, rgb(var(--et-cobalt-rgb) / 0.08), transparent 34%),
    radial-gradient(ellipse at 50% 74%, rgb(var(--et-pastel-rgb) / 0.22), transparent 42%),
    linear-gradient(135deg, var(--et-surface), color-mix(in srgb, var(--et-surface) 82%, var(--et-silver) 12%, var(--et-pastel) 6%));
  pointer-events: none;
}

.brain-3d-modal canvas {
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100%;
  height: 100%;
}

.brain-3d-topbar {
  position: absolute;
  top: 14px;
  left: 14px;
  right: 14px;
  z-index: 4;
  display: flex;
  justify-content: space-between;
  gap: 14px;
  pointer-events: none;
}

.brain-3d-title,
.brain-3d-topbar > button,
.brain-3d-controls,
.brain-3d-legend {
  border: 1px solid var(--et-border);
  border-radius: 8px;
  background: var(--et-panel);
  box-shadow: var(--et-shadow);
  backdrop-filter: blur(18px);
}

.brain-3d-title {
  padding: 10px 12px;
}

.brain-3d-topbar span {
  display: block;
  color: rgb(var(--et-dark-blue-rgb) / 0.6);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.brain-3d-topbar strong {
  display: block;
  margin-top: 4px;
  color: var(--et-ink);
  font-size: 13px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.brain-3d-topbar > button {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  color: var(--et-blue);
  cursor: pointer;
  pointer-events: auto;
}

.brain-3d-controls {
  display: flex;
  align-items: stretch;
  gap: 6px;
  margin-left: auto;
  padding: 4px;
  pointer-events: auto;
}

.brain-3d-controls label {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 7px;
}

.brain-3d-controls span {
  color: rgb(var(--et-dark-blue-rgb) / 0.58);
  font-size: 9.5px;
  font-weight: 780;
  letter-spacing: 0;
  text-transform: uppercase;
}

.brain-3d-controls select {
  min-width: 78px;
  border: 1px solid rgb(var(--et-cobalt-rgb) / 0.24);
  border-radius: 6px;
  padding: 5px 7px;
  color: var(--et-blue);
  background: var(--et-surface);
  font: inherit;
  font-size: 10.5px;
  font-weight: 760;
}

.brain-3d-controls button {
  min-width: 62px;
  border: 1px solid var(--et-border-active);
  border-radius: 7px;
  background: rgb(var(--et-cobalt-rgb) / 0.055);
  color: var(--et-blue);
  cursor: pointer;
  font: inherit;
  font-size: 10.5px;
  font-weight: 780;
}

.brain-3d-controls button.active {
  border-color: rgb(var(--et-mint-rgb) / 0.44);
  color: var(--et-ink);
  background:
    linear-gradient(135deg, rgb(var(--et-mint-rgb) / 0.14), rgb(var(--et-pastel-rgb) / 0.2));
}

.brain-3d-loader {
  z-index: 5;
}

.brain-3d-legend {
  position: absolute;
  right: 16px;
  bottom: 16px;
  z-index: 4;
  display: flex;
  gap: 14px;
  padding: 10px 12px;
  color: rgb(var(--et-dark-blue-rgb) / 0.66);
  font-size: 11px;
  font-weight: 700;
}

/* Dark 3D shell direction */
.neural-cockpit {
  grid-template-rows: 54px minmax(0, 1fr) 42px;
  gap: 8px;
  padding: 10px;
  background:
    linear-gradient(90deg, rgb(var(--et-mint-rgb) / 0.03), transparent 28%, rgb(var(--et-cobalt-rgb) / 0.04)),
    var(--et-black);
}

.et-topbar {
  grid-template-columns: 188px minmax(172px, 230px) minmax(280px, 1fr) repeat(5, minmax(86px, 116px));
  gap: 8px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.08);
