/* Shell correction pass: controlled palette, custom brain menu, overflow hardening */
:root {
  --et-page-bg: #070b12;
  --et-panel-bg: rgb(var(--et-dark-blue-rgb) / 0.82);
  --et-panel-bg-strong: rgb(var(--et-dark-blue-rgb) / 0.94);
  --et-panel-bg-soft: rgb(var(--et-dust-blue-rgb) / 0.26);
  --et-control-bg: rgb(var(--et-black-rgb) / 0.38);
  --et-control-bg-hover: rgb(var(--et-dust-blue-rgb) / 0.34);
  --et-control-border: rgb(var(--et-pastel-rgb) / 0.18);
  --et-control-border-active: rgb(var(--et-cobalt-rgb) / 0.44);
  --et-text: #ffffff;
  --et-text-muted: rgb(var(--et-silver-rgb) / 0.82);
  --et-text-soft: rgb(var(--et-silver-rgb) / 0.64);
}

body {
  background:
    radial-gradient(ellipse at 18% 70%, rgb(var(--et-mint-rgb) / 0.08), transparent 30%),
