/* Unified dropdown system */
.et-dropdown {
  min-width: 0;
  width: 100%;
}

.et-dropdown-trigger {
  width: 100%;
  min-width: 0;
  min-height: 40px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 16px;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--et-control-border);
  border-radius: 7px;
  padding: 6px 9px;
  color: var(--et-text);
  background:
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.34), rgb(var(--et-dust-blue-rgb) / 0.18));
  cursor: pointer;
  text-align: left;
}

.et-dropdown-trigger:hover:not(:disabled),
.et-dropdown.open .et-dropdown-trigger {
  border-color: rgb(var(--et-mint-rgb) / 0.42);
  background:
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.42), rgb(var(--et-dust-blue-rgb) / 0.26));
}

.et-dropdown-trigger:disabled {
  cursor: wait;
  opacity: 0.72;
}

.et-dropdown-content {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.et-dropdown-label {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  overflow: hidden;
  color: var(--et-text-muted);
  font-size: 9px;
  font-weight: 850;
  line-height: 1;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.et-dropdown-icon,
.et-dropdown-chevron {
  flex: 0 0 auto;
  color: var(--et-mint);
}

.et-dropdown-chevron {
  justify-self: end;
  transition: transform 160ms ease;
}

.et-dropdown.open .et-dropdown-chevron {
  transform: rotate(180deg);
}

.et-dropdown-trigger strong,
.et-dropdown-trigger em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.et-dropdown-trigger strong {
  color: var(--et-text);
  font-size: 10.5px;
  font-weight: 900;
  line-height: 1.1;
  text-transform: uppercase;
}

.et-dropdown-trigger em {
  color: var(--et-text-soft);
  font-size: 9px;
  font-style: normal;
  font-weight: 720;
  line-height: 1.1;
}

.et-dropdown-menu {
  position: fixed;
  z-index: 10000;
  max-height: min(360px, calc(100vh - 92px));
  overflow: auto;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.28);
  border-radius: 8px;
  padding: 6px;
  background:
    linear-gradient(180deg, rgb(var(--et-dark-blue-rgb) / 0.98), rgb(var(--et-black-rgb) / 0.96)),
    var(--et-dark-blue);
  box-shadow: 0 24px 70px rgb(0 0 0 / 0.44);
}

.et-dropdown-menu button {
  width: 100%;
  min-width: 0;
  display: grid;
  gap: 3px;
  border: 1px solid transparent;
  border-radius: 7px;
  padding: 8px 9px;
  color: var(--et-text);
  background: transparent;
  cursor: pointer;
  text-align: left;
}

.et-dropdown-menu button:hover,
.et-dropdown-menu button.selected {
  border-color: rgb(var(--et-cobalt-rgb) / 0.34);
  background:
    linear-gradient(135deg, rgb(var(--et-cobalt-rgb) / 0.18), rgb(var(--et-mint-rgb) / 0.08));
}

.et-dropdown-menu button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.et-dropdown-menu strong,
.et-dropdown-menu span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.et-dropdown-menu strong {
  color: var(--et-text);
  font-size: 10.5px;
  line-height: 1.2;
}

.et-dropdown-menu span {
  color: var(--et-text-soft);
  font-size: 9.5px;
  line-height: 1.2;
}

.brain-selector {
  padding: 6px 10px;
}

.brain-selector .et-dropdown-trigger {
  min-height: 31px;
  padding: 4px 8px;
}

.brain-3d-controls .et-dropdown,
.brain-layer-controls .et-dropdown {
