}

.brain-selector .et-dropdown-label,
.brain-3d-controls .et-dropdown-label,
.brain-layer-controls .et-dropdown-label,
.mission-select-group .et-dropdown-label {
  display: flex;
  margin: 0;
  color: var(--et-text-muted);
  line-height: 1;
