.brain-selector .et-dropdown-icon,
.brain-3d-controls .et-dropdown-icon,
.brain-layer-controls .et-dropdown-icon,
.mission-select-group .et-dropdown-icon {
  display: inline-flex;
  align-items: center;
  margin: 0;
}

.brain-selector .et-dropdown-content,
.brain-3d-controls .et-dropdown-content,
.brain-layer-controls .et-dropdown-content,
.mission-select-group .et-dropdown-content {
  display: grid;
}

.brain-3d-controls .et-dropdown-trigger em,
.brain-layer-controls .et-dropdown-trigger em,
.mission-select-group .et-dropdown-trigger em {
