  background: rgb(var(--et-black-rgb) / 0.22);
  font-size: 10px;
  font-weight: 900;
}

.guided-step strong,
.guided-inspector strong,
.guided-proof-tabs button {
  font-family: var(--et-display-font);
  letter-spacing: 0;
}

.guided-step strong {
  display: block;
  overflow: hidden;
  color: rgb(var(--et-silver-rgb) / 0.92);
  font-size: 11px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.guided-step em {
  display: block;
  overflow: hidden;
  margin-top: 2px;
  color: rgb(var(--et-dust-blue-rgb) / 0.72);
  font-size: 10px;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.guided-step-complete {
  border-color: rgb(var(--et-mint-rgb) / 0.22);
}

.guided-step-complete > span,
.guided-step-active > span {
  border-color: rgb(var(--et-mint-rgb) / 0.45);
  color: var(--et-mint);
  box-shadow: 0 0 22px rgb(var(--et-mint-rgb) / 0.14);
}

.guided-step-active {
  border-color: rgb(var(--et-mint-rgb) / 0.42);
  background:
    radial-gradient(ellipse at 0% 50%, rgb(var(--et-mint-rgb) / 0.14), transparent 52%),
    linear-gradient(135deg, rgb(var(--et-deep-navy-rgb) / 0.66), rgb(var(--et-black-rgb) / 0.2));
}

.guided-step-blocked {
  border-color: rgb(var(--et-dust-blue-rgb) / 0.38);
}

.guided-step-blocked > span {
  border-color: rgb(var(--et-dust-blue-rgb) / 0.5);
  color: var(--et-pastel);
}

.guided-inspector {
  min-height: 0;
  display: grid;
  gap: 6px;
  border: 1px solid rgb(var(--et-mint-rgb) / 0.18);
  border-radius: 8px;
  padding: 8px;
  background:
    radial-gradient(ellipse at 0% 0%, rgb(var(--et-mint-rgb) / 0.12), transparent 44%),
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.36), rgb(var(--et-deep-navy-rgb) / 0.32));
}

.guided-inspector-head {
  display: grid;
  gap: 4px;
}

.guided-inspector-head span {
  color: rgb(var(--et-mint-rgb) / 0.76);
  font-size: 10px;
  font-weight: 860;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.guided-inspector-head strong {
  color: var(--et-silver);
  font-size: 15px;
  line-height: 1.1;
}

.guided-inspector-head p {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: rgb(var(--et-pastel-rgb) / 0.74);
  font-size: 11.5px;
  line-height: 1.38;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.guided-inspector .definition-rows {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px 8px;
  border-top: 1px solid rgb(var(--et-silver-rgb) / 0.08);
  padding-top: 6px;
}

.guided-inspector .definition-rows div {
  grid-template-columns: 1fr;
  gap: 2px;
  align-content: start;
  border-bottom: 0;
  border-radius: 6px;
  padding: 5px 6px;
  background: rgb(var(--et-black-rgb) / 0.16);
}

.guided-inspector .definition-rows dt {
  overflow: hidden;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.guided-inspector .definition-rows dd {
  font-size: 11px;
  line-height: 1.2;
}

.guided-inspector-ready {
  border-color: rgb(var(--et-mint-rgb) / 0.28);
}

.guided-inspector-live {
  border-color: rgb(var(--et-cobalt-rgb) / 0.4);
  box-shadow: inset 0 0 0 1px rgb(var(--et-cobalt-rgb) / 0.08), 0 0 34px rgb(var(--et-cobalt-rgb) / 0.08);
}

.guided-inspector-blocked {
  border-color: rgb(var(--et-dust-blue-rgb) / 0.42);
}

.guided-proof-drawer {
  min-height: 0;
  display: grid;
  grid-template-rows: 36px minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.12);
  border-radius: 9px;
  background:
    linear-gradient(145deg, rgb(var(--et-deep-navy-rgb) / 0.48), rgb(var(--et-black-rgb) / 0.2)),
    rgb(var(--et-white-rgb) / 0.025);
}

.guided-proof-tabs {
  display: flex;
  gap: 6px;
  align-items: center;
  overflow: auto hidden;
  border-bottom: 1px solid rgb(var(--et-silver-rgb) / 0.09);
  padding: 6px;
}

.guided-proof-tabs button {
  min-height: 24px;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.12);
  border-radius: 7px;
  padding: 0 11px;
  color: rgb(var(--et-pastel-rgb) / 0.74);
  background: rgb(var(--et-black-rgb) / 0.16);
  font-size: 11px;
  font-weight: 820;
}

.guided-proof-tabs button.active {
  border-color: rgb(var(--et-mint-rgb) / 0.45);
  color: var(--et-silver);
  background:
    radial-gradient(ellipse at 20% 0%, rgb(var(--et-mint-rgb) / 0.18), transparent 48%),
    rgb(var(--et-cobalt-rgb) / 0.08);
  box-shadow: 0 0 20px rgb(var(--et-mint-rgb) / 0.08);
}

.guided-proof-tabs button.guided-proof-tab-blocked.active {
  border-color: rgb(var(--et-pastel-rgb) / 0.42);
}

.guided-proof-panel {
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(3, minmax(240px, 1fr));
  gap: 10px;
  overflow: auto;
  padding: 10px;
  scrollbar-color: rgb(var(--et-pastel-rgb) / 0.48) transparent;
  scrollbar-width: thin;
}

.guided-proof-panel .mode-panel {
  min-height: 0;
  background:
    linear-gradient(145deg, rgb(var(--et-deep-navy-rgb) / 0.46), rgb(var(--et-black-rgb) / 0.14)),
    rgb(var(--et-white-rgb) / 0.025);
}

.guided-proof-panel .mode-panel h2 {
  font-size: 12px;
}

.guided-proof-panel .evidence-list,
.guided-proof-panel .maintenance-proposal-review,
.guided-proof-panel .matrix-vector-review {
  max-height: none;
}

@media (max-width: 1280px) {
