  32% {
    opacity: 1;
    transform: translateY(-4px);
  }
}

@keyframes clone-app-thinking-scan {
  0%,
  18% {
    transform: translateX(-100%);
  }

  62% {
    transform: translateX(100%);
  }

  100% {
    transform: translateX(100%);
  }
}

@keyframes clone-presence-bar {
  0%,
  100% {
    opacity: 0.34;
    transform: scaleY(0.42);
  }

  42% {
    opacity: 0.96;
    transform: scaleY(1);
  }
}

@keyframes clone-presence-scan {
