.clone-app-shell {
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-columns: minmax(210px, 0.22fr) minmax(0, 1fr);
  gap: 14px;
}

.clone-app-nav,
.clone-app-main {
  min-width: 0;
  min-height: 0;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.1);
  border-radius: 8px;
  background: rgb(var(--et-black-rgb) / 0.24);
  box-shadow: inset 0 0 0 1px rgb(var(--et-white-rgb) / 0.018);
}

.clone-app-nav {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
}

.clone-app-nav-head {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  border-bottom: 1px solid rgb(var(--et-silver-rgb) / 0.08);
  padding-bottom: 12px;
}

.clone-app-nav-head svg,
.clone-app-brain-pulse svg,
.clone-app-source-grid svg {
  color: rgb(var(--et-mint-rgb) / 0.9);
}

.clone-app-nav-head span,
.clone-app-route-copy span,
.clone-app-policy-list span,
.clone-app-proof-grid span,
.clone-app-source-grid span,
.clone-app-flow-lanes span {
  color: rgb(var(--et-pastel-rgb) / 0.64);
  font-size: 10px;
  font-weight: 880;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.clone-app-nav-head strong {
  display: block;
  min-width: 0;
  overflow: hidden;
  color: rgb(var(--et-pale-silver-rgb) / 0.96);
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.clone-app-nav nav {
  min-height: 0;
  display: grid;
  align-content: start;
  gap: 8px;
}

.clone-app-nav button {
  min-width: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 9px;
  align-items: center;
  border: 1px solid rgb(var(--et-silver-rgb) / 0.1);
