/* Operation redesign layer: reusable review board used by Grow now and by
   Maintain/Sleep/Evolve/Matrix in the following slices. */
.operation-review-board {
  min-width: 0;
  min-height: 0;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto auto;
  gap: 10px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.16);
  border-radius: 10px;
  padding: 10px;
  background:
    radial-gradient(ellipse at 12% 0%, rgb(var(--et-mint-rgb) / 0.12), transparent 44%),
    radial-gradient(ellipse at 92% 0%, rgb(var(--et-cobalt-rgb) / 0.11), transparent 42%),
    linear-gradient(145deg, rgb(var(--et-dark-blue-rgb) / 0.7), rgb(var(--et-black-rgb) / 0.5));
  box-shadow: inset 0 0 0 1px rgb(var(--et-white-rgb) / 0.025), 0 20px 54px rgb(0 0 0 / 0.2);
}

.operation-review-board-head {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, auto);
  gap: 12px;
  align-items: start;
}

.operation-review-board-head > div:first-child {
  min-width: 0;
}

.operation-review-board-head span,
.operation-review-board-filters legend,
.operation-item-queue-head span,
.operation-item-row-main span,
.operation-item-focus > header span,
.operation-item-memory span,
.operation-item-source span,
.operation-item-metadata span,
.operation-review-board-actions > span,
.operation-coach-popup strong {
  color: rgb(var(--et-mint-rgb) / 0.86);
  font-size: 9px;
  font-weight: 880;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-transform: uppercase;
}

.operation-review-board-head strong {
  display: block;
  margin-top: 4px;
  overflow: hidden;
  color: rgb(var(--et-pale-silver-rgb) / 0.96);
  font-family: var(--et-display-font);
  font-size: clamp(18px, 1.45vw, 24px);
  font-weight: 900;
  line-height: 1.08;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.operation-review-board-head p {
  max-width: 780px;
  margin: 5px 0 0;
  color: rgb(var(--et-silver-rgb) / 0.74);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
}

.operation-review-board-stats {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(4, minmax(56px, 1fr));
  gap: 7px;
}

.operation-review-board-stats article {
  min-width: 0;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.12);
  border-radius: 8px;
  padding: 7px 8px;
  background: rgb(var(--et-black-rgb) / 0.28);
}

.operation-review-board-stats span {
  display: block;
  overflow: hidden;
  color: rgb(var(--et-silver-rgb) / 0.64);
  font-size: 8px;
  font-weight: 820;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.operation-review-board-stats strong {
  display: block;
  margin-top: 4px;
  color: rgb(var(--et-pale-silver-rgb) / 0.95);
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
}

.operation-review-board-filters {
  min-width: 0;
}

.operation-review-board-filters .et-segmented-control {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.operation-review-board-grid {
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(250px, 0.46fr) minmax(0, 1fr);
  gap: 10px;
}

.operation-item-queue,
.operation-item-focus {
  min-width: 0;
  min-height: 0;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.13);
  border-radius: 9px;
  background:
    linear-gradient(145deg, rgb(var(--et-black-rgb) / 0.32), rgb(var(--et-dark-blue-rgb) / 0.34)),
    rgb(var(--et-black-rgb) / 0.16);
}

.operation-item-queue {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
}

.operation-item-queue-head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 7px;
  align-items: center;
  border-bottom: 1px solid rgb(var(--et-pastel-rgb) / 0.1);
  padding: 9px 10px;
}

.operation-item-queue-head svg {
  color: var(--et-mint);
}

.operation-item-queue-head strong {
  color: rgb(var(--et-pale-silver-rgb) / 0.9);
  font-size: 12px;
}

.operation-item-queue-list {
  min-height: 0;
  display: grid;
  align-content: start;
  gap: 8px;
  overflow: auto;
  padding: 8px;
}

.operation-item-row {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 76px;
  gap: 8px;
  border: 1px solid rgb(var(--et-pastel-rgb) / 0.12);
  border-radius: 8px;
  padding: 7px;
  background: rgb(var(--et-black-rgb) / 0.26);
