/* Product-Convergence-0B: shared AGVM product shell foundation. */
.agvm-product-shell {
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  height: 100vh;
  min-height: 100vh;
  overflow: hidden;
  color: #f7fbff;
  background:
    radial-gradient(circle at 20% 5%, rgb(23 184 166 / 0.16), transparent 28%),
    radial-gradient(circle at 82% 2%, rgb(79 140 255 / 0.14), transparent 26%),
    linear-gradient(135deg, #071019 0%, #0a1220 48%, #060b13 100%);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  letter-spacing: 0;
}

.agvm-product-shell *,
.agvm-product-shell *::before,
.agvm-product-shell *::after {
  box-sizing: border-box;
}

.agvm-product-topbar {
  position: sticky;
  z-index: 4;
  top: 0;
  display: grid;
  grid-template-columns: minmax(210px, 0.45fr) minmax(520px, 1fr) minmax(190px, 0.34fr);
  gap: 16px;
  align-items: stretch;
  min-height: 76px;
  padding: 12px 18px;
  border-bottom: 1px solid rgb(162 184 214 / 0.14);
  background: rgb(6 11 18 / 0.86);
  backdrop-filter: blur(18px);
}

.agvm-product-brand,
.agvm-product-session,
.agvm-product-context-tile,
.agvm-product-usage-tile,
.agvm-product-brain-select,
.agvm-product-sidebar-card,
.agvm-product-page-header,
.agvm-product-empty-state,
.agvm-product-metric-card,
.agvm-product-module-card {
  border: 1px solid rgb(162 184 214 / 0.14);
  border-radius: 8px;
  background:
    linear-gradient(145deg, rgb(15 24 38 / 0.78), rgb(8 13 22 / 0.68)),
    rgb(8 13 22 / 0.92);
  box-shadow: 0 20px 60px rgb(0 0 0 / 0.18);
}

.agvm-product-brand {
  display: flex;
  gap: 12px;
  align-items: center;
  min-width: 0;
  padding: 12px 14px;
}

.agvm-product-mark {
  display: inline-grid;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid rgb(23 184 166 / 0.38);
  border-radius: 8px;
  color: #19d5c4;
  background: linear-gradient(145deg, rgb(23 184 166 / 0.14), rgb(79 140 255 / 0.1));
}

.agvm-product-brand strong,
.agvm-product-session strong,
.agvm-product-context-tile strong,
.agvm-product-usage-tile strong,
.agvm-product-brain-select select,
.agvm-product-page-header h1,
.agvm-product-empty-state strong,
.agvm-product-metric-card strong,
.agvm-product-module-card strong {
  color: #f8fbff;
  font-weight: 720;
}

.agvm-product-brand span,
.agvm-product-session span,
.agvm-product-context-tile span,
.agvm-product-context-tile em,
.agvm-product-usage-tile span,
.agvm-product-brain-select span,
.agvm-product-page-header p,
.agvm-product-empty-state p,
.agvm-product-metric-card p,
.agvm-product-module-card p,
.agvm-product-module-card span,
.agvm-product-sidebar-card p,
.agvm-product-sidebar-card span {
  color: #a8b5c6;
  font-size: 12px;
  line-height: 1.42;
}

.agvm-product-brand strong {
  display: block;
  font-size: 20px;
  line-height: 1;
}

.agvm-product-context-strip {
  display: grid;
  grid-template-columns: minmax(150px, 0.85fr) minmax(210px, 1.2fr) minmax(150px, 0.82fr) minmax(220px, 1fr);
  gap: 10px;
  min-width: 0;
}

.agvm-product-context-tile,
.agvm-product-usage-tile,
.agvm-product-brain-select {
  display: grid;
  align-content: center;
  min-width: 0;
  padding: 10px 12px;
}

.agvm-product-context-tile strong,
.agvm-product-usage-tile strong {
  overflow: hidden;
  font-size: 14px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-brain-select > div {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) 16px;
  gap: 8px;
  align-items: center;
  min-width: 0;
}

.agvm-product-brain-select svg {
  color: #19d5c4;
}

.agvm-product-brain-select select {
  min-width: 0;
  border: 0;
  outline: 0;
  color: #f8fbff;
  background: transparent;
  font-size: 14px;
  appearance: none;
}

.agvm-product-meter {
  overflow: hidden;
  height: 5px;
  margin-top: 8px;
  border-radius: 999px;
  background: rgb(162 184 214 / 0.12);
}

.agvm-product-meter i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #19d5c4, #4f8cff);
}

.agvm-product-session {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) 34px;
  gap: 10px;
  align-items: center;
  min-width: 0;
  padding: 10px 12px;
}

.agvm-product-session > div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.agvm-product-session strong,
.agvm-product-session span:not(.agvm-product-avatar) {
  display: block;
  overflow: hidden;
  min-width: 0;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-avatar {
  display: inline-grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgb(127 112 255 / 0.58);
  border-radius: 999px;
  color: #f8fbff !important;
  background: rgb(127 112 255 / 0.13);
  font-size: 12px !important;
  font-weight: 800;
}

.agvm-product-status-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: #a8b5c6;
}

.agvm-product-status-dot.ready,
.agvm-product-status-dot.active {
  background: #19d5c4;
  box-shadow: 0 0 14px rgb(25 213 196 / 0.42);
}

.agvm-product-status-dot.pending,
.agvm-product-status-dot.neutral {
  background: #4f8cff;
}

.agvm-product-status-dot.degraded,
.agvm-product-status-dot.blocked {
  background: #ffbd66;
}

.agvm-product-layout {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr) 340px;
  gap: 16px;
  min-height: 0;
  overflow: hidden;
  padding: 16px;
}

.agvm-product-layout.without-module-rail {
  grid-template-columns: 220px minmax(0, 1fr);
}

.agvm-product-sidebar {
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 16px;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}

.agvm-product-sidebar nav {
  display: grid;
  align-content: start;
  gap: 8px;
  min-height: 0;
  overflow: auto;
  scrollbar-width: thin;
}

.agvm-product-nav-item {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 44px;
  min-width: 0;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 9px 10px;
  color: #c7d2e2;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.agvm-product-nav-item:hover,
.agvm-product-nav-item.active {
  border-color: rgb(79 140 255 / 0.34);
  color: #f8fbff;
  background: linear-gradient(90deg, rgb(79 140 255 / 0.2), rgb(25 213 196 / 0.07));
}

.agvm-product-nav-item svg {
  color: #8aa0bd;
}

.agvm-product-nav-item.active svg {
  color: #19d5c4;
}

.agvm-product-nav-item span {
  overflow: hidden;
  font-size: 14px;
  font-weight: 650;
  line-height: 1.1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-nav-item em {
  color: #8aa0bd;
  font-size: 10px;
  font-style: normal;
  text-transform: uppercase;
}

.agvm-product-sidebar-card {
  display: grid;
  gap: 6px;
  padding: 14px;
}

.agvm-product-sidebar-card strong {
  color: #f8fbff;
}

.agvm-product-main {
  display: grid;
  grid-template-rows: auto minmax(360px, 1fr) auto;
  gap: 14px;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}

.agvm-product-page-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 20px;
}

.agvm-product-page-header > div:first-child {
  min-width: 0;
}

.agvm-product-page-header span {
  color: #19d5c4;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.agvm-product-page-header h1 {
  margin: 4px 0 6px;
  font-size: 28px;
  line-height: 1.05;
  letter-spacing: 0;
}

.agvm-product-page-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  min-width: min(420px, 100%);
}

.agvm-product-primary-action,
.agvm-product-module-card button {
  border: 1px solid rgb(25 213 196 / 0.34);
  border-radius: 8px;
  color: #f8fbff;
  background: linear-gradient(100deg, #17b8a6, #4f6fff);
  font-size: 13px;
  font-weight: 750;
  cursor: pointer;
}

.agvm-product-primary-action {
  display: inline-grid;
  place-items: center;
  min-height: 36px;
  padding: 0 14px;
  text-decoration: none;
}

.agvm-product-content {
  min-width: 0;
  min-height: 0;
  overflow: auto;
  border: 1px solid rgb(162 184 214 / 0.12);
  border-radius: 8px;
  background: rgb(8 13 22 / 0.48);
}

.agvm-product-shell[data-active-route="clone_app"] .agvm-product-main,
.agvm-product-shell[data-active-route="grow"] .agvm-product-main,
.agvm-product-shell[data-active-route="maintain"] .agvm-product-main {
  grid-template-rows: auto minmax(0, 1fr);
}

.agvm-product-shell[data-active-route="clone_app"] .agvm-product-metrics,
.agvm-product-shell[data-active-route="grow"] .agvm-product-metrics,
.agvm-product-shell[data-active-route="maintain"] .agvm-product-metrics {
  display: none;
}

.agvm-product-shell[data-active-route="clone_app"] .agvm-product-content {
  overflow: hidden;
}

.agvm-product-shell[data-active-route="clone_app"] .agvm-native-runtime-embed[data-cockpit-mode="clone_app"] {
  align-content: stretch;
  height: 100%;
}

.agvm-product-shell[data-active-route="clone_app"] .clone-app-shell.frame-managed {
  height: 100%;
