/* UI-POLISH-1: premium product-shell pass.
   Goal: preserve the restored shared native runtime while making the shell feel like a
   real work surface: compact chrome, more useful vertical room, clearer scroll
   boundaries and fewer nested-card visual collisions. */
.agvm-product-shell {
  --agvm-shell-bg: #050a12;
  --agvm-shell-surface: rgb(10 17 28 / 0.82);
  --agvm-shell-surface-soft: rgb(10 17 28 / 0.56);
  --agvm-shell-border: rgb(163 183 214 / 0.12);
  --agvm-shell-border-strong: rgb(120 143 180 / 0.2);
  --agvm-shell-text: #f5f8fc;
  --agvm-shell-muted: #9ca9bb;
  --agvm-shell-subtle: #6f819a;
  --agvm-shell-teal: #23d0bd;
  --agvm-shell-blue: #4c7df2;
  background:
    linear-gradient(180deg, rgb(8 15 25 / 0.96), rgb(4 8 14 / 0.98)),
    var(--agvm-shell-bg);
}

.agvm-product-topbar {
  grid-template-columns: minmax(210px, 274px) minmax(0, 1fr) minmax(180px, 230px);
  gap: 10px;
  min-height: 68px;
  padding: 9px 14px;
  border-bottom-color: var(--agvm-shell-border);
  background:
    linear-gradient(180deg, rgb(8 14 23 / 0.96), rgb(5 10 18 / 0.92)),
    var(--agvm-shell-bg);
  backdrop-filter: blur(20px);
}

.agvm-product-brand,
.agvm-product-session,
.agvm-product-context-tile,
.agvm-product-usage-tile,
.agvm-product-brain-select,
.agvm-product-sidebar-card,
.agvm-product-page-header,
.agvm-product-empty-state,
.agvm-product-metric-card,
.agvm-product-module-card {
  border-color: var(--agvm-shell-border);
  border-radius: 10px;
  background:
    linear-gradient(145deg, rgb(16 24 38 / 0.66), rgb(6 11 19 / 0.7)),
    var(--agvm-shell-surface);
  box-shadow: none;
}

.agvm-product-brand {
  gap: 10px;
  padding: 9px 12px;
}

.agvm-product-mark {
  flex-basis: 34px;
