/* FINAL-5A: shared AGVM premium shell chrome.
   The local and cloud products keep one shell, but the module rail now has a
   route-aware presentation so the work area remains primary and every page owns
   a clear scroll container. */
.agvm-product-shell {
  --agvm-shell-bg: #050914;
  --agvm-shell-surface: rgb(9 16 28 / 0.84);
  --agvm-shell-surface-soft: rgb(12 21 34 / 0.58);
  --agvm-shell-border: rgb(151 173 205 / 0.14);
  --agvm-shell-border-strong: rgb(52 211 196 / 0.28);
  --agvm-shell-text: #f7fbff;
  --agvm-shell-muted: #a7b3c5;
  --agvm-shell-subtle: #74849d;
  --agvm-shell-teal: #2de0c5;
  --agvm-shell-blue: #4d83ff;
  --agvm-shell-violet: #896dff;
  color: var(--agvm-shell-text);
  background:
    linear-gradient(180deg, rgb(6 12 22 / 0.98), rgb(3 8 15 / 0.99)),
    repeating-linear-gradient(90deg, rgb(255 255 255 / 0.018) 0 1px, transparent 1px 76px),
    var(--agvm-shell-bg);
  height: 100vh;
  min-height: 0;
  overflow: hidden;
}

.agvm-product-topbar {
  grid-template-columns: minmax(230px, 282px) minmax(0, 1fr) minmax(218px, 248px);
  align-items: stretch;
  gap: 12px;
  min-height: 72px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--agvm-shell-border);
  background:
    linear-gradient(180deg, rgb(8 15 27 / 0.97), rgb(4 9 17 / 0.94)),
    var(--agvm-shell-bg);
}

.agvm-product-brand,
.agvm-product-session,
.agvm-product-context-tile,
.agvm-product-usage-tile,
.agvm-product-brain-select,
.agvm-product-page-header,
.agvm-product-metric-card,
.agvm-product-module-card,
.agvm-product-empty-state {
  border: 1px solid var(--agvm-shell-border);
