}

.agvm-product-context-tile strong,
.agvm-product-usage-tile strong,
.agvm-product-brain-select select,
.agvm-product-session strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-layout.with-module-rail.module-rail-compact {
  grid-template-columns: minmax(206px, 218px) minmax(0, 1fr) minmax(238px, 278px);
}

.agvm-product-layout.with-module-rail.module-rail-expanded {
