}

.agvm-product-layout.without-module-rail,
.agvm-product-layout.module-rail-hidden {
  grid-template-columns: minmax(206px, 218px) minmax(0, 1fr);
}

.agvm-product-layout {
  gap: 12px;
  min-height: 0;
  overflow: hidden;
  padding: 12px;
}

.agvm-product-sidebar {
  grid-template-rows: minmax(0, 1fr) auto;
  gap: 10px;
  overflow: hidden;
}

.agvm-product-sidebar nav {
  align-content: start;
  gap: 6px;
  overflow: auto;
  padding-right: 2px;
  scrollbar-color: rgb(45 224 197 / 0.38) transparent;
  scrollbar-width: thin;
}

.agvm-product-nav-item {
  grid-template-columns: 20px minmax(0, 1fr);
  column-gap: 10px;
  row-gap: 2px;
  min-height: 44px;
  border-radius: 8px;
  padding: 8px 10px;
}

.agvm-product-nav-item span {
  overflow: visible;
  font-size: 13px;
  line-height: 1.12;
  text-overflow: clip;
  white-space: normal;
}

.agvm-product-nav-item em {
  grid-column: 2;
  max-width: 100%;
  overflow: visible;
  color: var(--agvm-shell-subtle);
  font-size: 9.5px;
  line-height: 1.1;
  text-overflow: clip;
  white-space: normal;
}

.agvm-product-nav-item.active {
  border-color: rgb(45 224 197 / 0.36);
  background:
    linear-gradient(90deg, rgb(77 131 255 / 0.2), rgb(45 224 197 / 0.09)),
    rgb(13 22 37 / 0.74);
  box-shadow: inset 3px 0 0 var(--agvm-shell-teal);
}

.agvm-product-main {
  grid-template-rows: auto minmax(0, 1fr) auto;
  min-height: 0;
  overflow: hidden;
}

.agvm-product-page-header {
  grid-template-columns: minmax(0, 1fr) minmax(220px, auto);
  gap: 12px;
  min-height: 88px;
  padding: 14px 16px;
}

.agvm-product-page-header h1 {
  margin: 2px 0 4px;
  font-size: clamp(21px, 1.35vw, 26px);
  line-height: 1.08;
}

.agvm-product-page-header p {
  max-width: 820px;
  margin: 0;
  color: var(--agvm-shell-muted);
  font-size: 12px;
  line-height: 1.38;
}

.agvm-product-page-actions {
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

.agvm-product-content {
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-color: rgb(45 224 197 / 0.4) transparent;
  scrollbar-width: thin;
}

.agvm-product-shell .agvm-native-runtime-embed.neural-cockpit.shell-v2[class*="shell-option-"] {
  display: grid !important;
  grid-template-rows: minmax(0, 1fr) !important;
  gap: 0 !important;
  height: 100% !important;
  min-height: 0 !important;
  min-width: 0 !important;
  max-width: 100% !important;
  padding: 0 !important;
  width: 100% !important;
}

.neural-cockpit.shell-v2.timeline-disabled[class*="shell-option-"] {
  grid-template-rows: 72px minmax(0, 1fr) !important;
}

.agvm-product-shell[data-module-rail="hidden"] .agvm-product-module-rail {
  display: none;
}

.agvm-product-module-rail {
  align-content: start;
  gap: 9px;
  min-height: 0;
  overflow: auto;
  padding: 0 3px 2px 0;
  scrollbar-color: rgb(45 224 197 / 0.36) transparent;
  scrollbar-width: thin;
}

.agvm-product-shell[data-module-rail="compact"] .agvm-product-module-card {
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 9px;
  padding: 10px;
}

.agvm-product-shell[data-module-rail="compact"] .agvm-product-module-icon {
  width: 34px;
  height: 34px;
}

.agvm-product-shell[data-module-rail="compact"] .agvm-product-module-card p {
  display: none;
}

.agvm-product-shell[data-module-rail="compact"] .agvm-product-module-card strong {
  overflow: hidden;
  display: block;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-shell[data-module-rail="compact"] .agvm-product-module-card em {
  overflow: hidden;
  display: block;
  margin-top: 3px;
  color: var(--agvm-shell-muted);
