  white-space: nowrap;
}

.agvm-product-shell[data-module-rail="compact"] .agvm-product-module-card button {
  grid-column: 1 / -1;
  min-height: 30px;
}

.agvm-product-shell[data-module-rail="expanded"] .agvm-product-module-card {
  grid-template-columns: 38px minmax(0, 1fr);
}

.agvm-product-shell-local:not([data-active-route="modules"]) .agvm-product-content {
  overflow-x: hidden;
  overflow-y: auto;
}

.agvm-product-shell-local[data-active-route="context"] .agvm-native-runtime-embed.neural-cockpit.shell-v2[class*="shell-option-"] .brain-stage-with-composer .brain-canvas-zone {
