}

.agvm-product-shell-local[data-active-route="context"] .agvm-product-page-header,
.agvm-product-shell-local[data-active-route="results"] .agvm-product-page-header,
.agvm-product-shell-local[data-active-route="health"] .agvm-product-page-header,
.agvm-product-shell-local[data-active-route="bench"] .agvm-product-page-header {
  min-height: 88px;
}

/* FINAL-5B: cloud Context route uses the shared native brain workspace */
.agvm-native-context-route {
  grid-template-columns: minmax(0, 1fr) minmax(260px, 320px);
  align-items: stretch;
  min-height: min(720px, calc(100vh - 236px));
  padding: 14px;
}

.agvm-native-context-workspace {
  display: grid;
  grid-template-rows: minmax(360px, 1fr) auto;
  gap: 14px;
  min-width: 0;
  min-height: 0;
}

.agvm-native-context-brain-stage,
.agvm-native-context-composer,
.agvm-native-context-side,
.agvm-native-context-result {
  border: 1px solid rgb(162 184 214 / 0.14);
  border-radius: 8px;
  background:
    radial-gradient(circle at 22% 18%, rgb(45 224 197 / 0.11), transparent 34%),
    linear-gradient(145deg, rgb(15 24 38 / 0.88), rgb(8 13 22 / 0.76)),
    rgb(8 13 22 / 0.94);
  box-shadow: 0 22px 70px rgb(0 0 0 / 0.18);
}

.agvm-native-context-brain-stage {
  position: relative;
  min-height: 360px;
  overflow: hidden;
}

.agvm-native-context-brain-stage .brain-3d-inline {
  height: 100%;
  min-height: 360px;
  border: 0;
  border-radius: 8px;
  background:
    radial-gradient(circle at 46% 34%, rgb(77 131 255 / 0.12), transparent 34%),
    rgb(4 8 15 / 0.92);
}

.agvm-native-context-brain-stage .brain-3d-scene,
.agvm-native-context-brain-stage canvas {
  min-height: 320px;
}

.agvm-native-context-live {
  position: absolute;
  right: 14px;
  bottom: 14px;
  left: 14px;
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  max-width: 460px;
  border: 1px solid rgb(162 184 214 / 0.16);
  border-radius: 8px;
  padding: 10px 12px;
  color: #f8fbff;
  background: rgb(7 12 20 / 0.82);
  backdrop-filter: blur(16px);
}

.agvm-native-context-live i {
  width: 9px;
  height: 9px;
  border-radius: 999px;
  background: rgb(45 224 197);
  box-shadow: 0 0 18px rgb(45 224 197 / 0.5);
}

.agvm-native-context-live.running i {
  background: rgb(79 140 255);
  box-shadow: 0 0 18px rgb(79 140 255 / 0.56);
}

.agvm-native-context-live span,
.agvm-native-context-side-head span,
.agvm-native-context-result span,
.agvm-native-context-composer > div > span {
  color: #19d5c4;
  font-size: 10px;
  font-weight: 820;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.agvm-native-context-live strong,
.agvm-native-context-side-head strong,
.agvm-native-context-result strong {
  overflow: hidden;
  display: block;
  margin-top: 3px;
  color: #f8fbff;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-native-context-live small,
.agvm-native-context-side-head p,
.agvm-native-context-result p,
.agvm-native-context-result em,
.agvm-native-context-composer p {
  margin: 0;
  color: #a8b5c6;
  font-size: 12px;
  line-height: 1.45;
}

.agvm-native-context-live small {
  overflow: hidden;
  display: block;
  margin-top: 2px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-native-context-composer {
  display: grid;
  grid-template-columns: minmax(260px, 0.86fr) minmax(320px, 1.14fr);
  gap: 14px;
  align-items: end;
  padding: 16px;
}

.agvm-native-context-composer h2 {
  margin: 3px 0 6px;
  color: #f8fbff;
  font-size: clamp(22px, 1.45vw, 30px);
  line-height: 1.04;
  letter-spacing: 0;
}

.agvm-native-context-composer label {
  display: grid;
  gap: 8px;
}

.agvm-native-context-composer label > span {
  color: #8da0b8;
  font-size: 10px;
  font-weight: 780;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.agvm-native-context-composer textarea {
  min-height: 108px;
  max-height: 180px;
  resize: vertical;
  border: 1px solid rgb(79 140 255 / 0.25);
  border-radius: 8px;
  padding: 14px;
  outline: 0;
  color: #f8fbff;
  background: rgb(5 10 18 / 0.82);
  font: inherit;
}

.agvm-native-context-composer textarea:focus {
  border-color: rgb(25 213 196 / 0.58);
  box-shadow: 0 0 0 3px rgb(25 213 196 / 0.12);
}

.agvm-native-context-composer .agvm-shared-action-row {
  grid-column: 2;
}

.agvm-native-context-composer .agvm-shared-action-result {
  grid-column: 1 / -1;
}

.agvm-native-context-side {
  display: grid;
  align-content: start;
  gap: 14px;
  min-width: 0;
  padding: 14px;
}

.agvm-native-context-side .agvm-shared-fact-grid {
  grid-template-columns: 1fr;
}

.agvm-native-context-side .agvm-shared-fact {
  min-height: 86px;
  padding: 13px;
}

.agvm-native-context-result {
  display: grid;
  gap: 8px;
  padding: 14px;
}

.agvm-native-context-result.muted {
  border-color: rgb(79 140 255 / 0.18);
}

.agvm-product-brain-select {
  gap: 4px;
}

.agvm-product-brain-select.missing {
  border-color: rgb(255 177 81 / 0.28);
}

.agvm-product-brain-select > .agvm-product-brain-control {
  display: grid;
