}

.agvm-product-brain-meta button:hover {
  border-color: rgb(45 224 197 / 0.46);
  background: rgb(45 224 197 / 0.14);
}

.agvm-product-brain-trigger {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) 16px;
  gap: 8px;
  align-items: center;
  width: 100%;
  min-height: 42px;
  border: 0;
  padding: 0;
  color: inherit;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.agvm-product-brain-trigger span {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.agvm-product-brain-trigger em {
  color: #19d5c4;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
  text-transform: uppercase;
}

.agvm-product-brain-trigger strong {
