  color: #f8fbff;
  font-size: 14px;
  line-height: 1.15;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-brain-select.open {
  z-index: 20;
  border-color: rgb(45 224 197 / 0.34);
}

.agvm-product-brain-select > .agvm-product-brain-menu {
  position: absolute;
  z-index: 25;
  inset-block-start: calc(100% + 8px);
