  box-shadow: 0 24px 80px rgb(0 0 0 / 0.42);
}

.agvm-product-brain-menu-head,
.agvm-product-brain-list {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.agvm-product-brain-menu-head span {
  color: #19d5c4;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.agvm-product-brain-menu-head strong {
  color: #f8fbff;
  font-size: 18px;
  line-height: 1.16;
}

.agvm-product-brain-menu-head p,
.agvm-product-brain-empty {
  margin: 0;
  color: #a8b5c6;
  font-size: 12px;
  line-height: 1.45;
}

.agvm-product-brain-menu-primary,
.agvm-product-brain-list button,
.agvm-product-brain-manage {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  align-items: center;
  min-height: 44px;
  border: 1px solid rgb(162 184 214 / 0.14);
  border-radius: 8px;
  padding: 10px;
  color: #dce8f8;
  background: rgb(8 14 24 / 0.72);
  text-align: left;
  text-decoration: none;
  cursor: pointer;
}

.agvm-product-brain-menu-primary {
  grid-template-columns: 18px minmax(0, 1fr);
  border-color: rgb(25 213 196 / 0.32);
  color: #f8fbff;
  background: linear-gradient(135deg, rgb(25 213 196 / 0.18), rgb(79 140 255 / 0.12));
  font-weight: 850;
}

.agvm-product-brain-list button strong {
  overflow: hidden;
  color: #f8fbff;
  font-size: 13px;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agvm-product-brain-list button span {
  color: #a8b5c6;
  font-size: 11px;
}

.agvm-product-brain-list button em {
  align-self: center;
  border: 1px solid rgb(162 184 214 / 0.14);
  border-radius: 999px;
  padding: 5px 8px;
  color: #cfe0f4;
  font-size: 10px;
  font-style: normal;
  font-weight: 850;
}

.agvm-product-brain-list button.selected {
  border-color: rgb(25 213 196 / 0.28);
  background: rgb(25 213 196 / 0.08);
}

.agvm-product-brain-list button:disabled {
  cursor: default;
  opacity: 0.86;
}

.agvm-product-brain-manage {
  color: #bffbf2;
  font-weight: 850;
}

.agvm-cloud-first-run-route,
.agvm-cloud-account-overview,
.agvm-cloud-settings-overview {
  align-content: start;
  gap: 14px;
}

.agvm-cloud-first-run-hero,
