.agvm-cloud-first-run-hero span,
.agvm-cloud-account-hero span,
.agvm-cloud-provider-setup span,
.agvm-cloud-brain-setup span,
.agvm-cloud-first-query span,
.agvm-cloud-account-card span,
.agvm-cloud-settings-section span {
  color: #19d5c4;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.agvm-cloud-first-run-hero h2,
.agvm-cloud-account-hero h2 {
  margin: 6px 0 8px;
  color: #f8fbff;
  font-size: clamp(30px, 4vw, 48px);
  line-height: 1;
